from src.masker import mask_phone

def log_message(message):
    return mask_phone(message)

def log_event(event, message, level='INFO', timestamp=None):
    return {'event': event, 'message': mask_phone(message), 'level': level, 'timestamp': timestamp}

import re

_PHONE_PATTERN = re.compile(
    r'(?<!\d)(0\d{1,2})([-\s]?)(\d{4})([-\s]?)(\d{4})(?!\d)'
)


def mask_phone(text):
    if not isinstance(text, str):
        return text
    return _PHONE_PATTERN.sub(r'\1\2****\4\5', text)

