import re

_PHONE_PATTERN = re.compile(r'(?<!\d)(0\d{1,2})([-\s]?)(\d{4})([-\s]?)(\d{4})(?!\d)')


def _mask_match(match):
    return match.group(1) + match.group(2) + '****' + match.group(4) + match.group(5)


def mask_phone(text):
    if not isinstance(text, str):
        return text
    return _PHONE_PATTERN.sub(_mask_match, text)

